package com.personal.assistant.module.backup.service;
import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.mapper.BackupRecordMapper;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.junit.jupiter.api.io.TempDir;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class BackupVerificationServiceTest{@Mock BackupRecordMapper records;@TempDir Path temp;@Test void verifyComputesDigestAndWarnsAboutRecovery()throws Exception{Path file=temp.resolve("backup.sql.gz");Files.writeString(file,"backup-data");BackupRecord record=new BackupRecord();record.setId(9L);record.setUserId(3L);record.setFilePath(file.toString());record.setFileSize(Files.size(file));when(records.selectById(9L)).thenReturn(record);var result=new BackupService(records).verify(3L,9L);assertEquals("VERIFIED",result.status());assertEquals(64,result.sha256().length());assertTrue(result.recoveryNotice().contains("恢复演练"));verify(records).updateById(record);}}
